# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Invoices::ReservationRequest do
  # "The intent must store the whole request, so retries and recovery resend the stored bytes and never recompute."
  it "stores entries once in canonical order so a resent request carries the same bytes" do
    operation_id = SecureRandom.uuid
    caller_entries = [3, 1, 3]
    request = described_class.new(company_id: 1, invoice_id: 10, operation_id:, generation: 1,
                                  disposition: "active", entries: caller_entries)
    caller_entries << 99

    expect(request.entries).to eq([1, 3])
    expect(request.entries).to be_frozen
    expect(caller_entries).not_to be_frozen
    expect(request).to eq(described_class.new(company_id: 1, invoice_id: 10, operation_id:, generation: 1,
                                              disposition: "active", entries: [1, 3]))
  end
end
